  "settings.communityShareHint": "“Dinlemelerim”den ayrıdır ve varsayılan olarak kapalıdır. Albüm puanlarınız (yorumsuz) ve hesabınızın bu özelliği açtıktan SONRA aldığı dinlemeler, herkese açık ve anonim toplamlara katılır; bu toplamlar en az üç farklı kişiden itibaren albüm sayfasında gösterilir. Hiçbir bireysel veri gösterilmez. Kapatmak katkınızı hemen kaldırır.",
  "settings.communityMeasuresReceive": "Topluluktan analiz sonuçlarını al",
  "settings.communityMeasuresReceiveHint": "Varsayılan olarak kapalı. Sunucu, FLAC dosyalarınız için mozaiklabs.fr sitesinden, en az iki başka kurulumun tamamen aynı sinyal üzerinde önceden ölçtüğü ReplayGain, dinamik aralık ve akustik parmak izi değerlerini ister. Bunlar yalnızca eksik olanı tamamlar: etiketleriniz ve kendi ölçümleriniz asla değiştirilmez. Site yalnızca kısa bir önek alır, dosyalarınızın listesini asla almaz.",
