  "upsampling.eyebrow": "Premium eklenti",
  "upsampling.title": "Upsampling",
  "upsampling.lead": "Yerel çıkışta kaynağın örnekleme hızını, DAC’ın kabul ettiği en yüksek hıza, aynı aileyi izleyerek yükseltir (44,1 → 352,8 kHz, 48 → 384 kHz). Seviye 3 dB düşürülür ve bir güvenlik sınırlayıcısı kalan nadir tepeleri tutar: hiç kırpılma olmaz. Tune ses düzeyi bu 3 dB’yi geri verir: ses düzeyi −3 dB veya altında olduğu sürece seviye, üst örneklemesiz çalma ile aynıdır (%100’de seviyeyi DAC’ta veya ön amfide ayarlayın).",
  "upsampling.noZone": "Upsampling ayarı için bir bölge seçin.",
  "upsampling.bitPerfect": "Etkinken upsampling her örneği değiştirir: yol artık bit-perfect değildir. PURE modu onu her zaman atlar ve bir DoP akışına asla upsampling uygulanmaz.",
  "upsampling.enabled": "Bu bölgeye upsampling uygula",
  "upsampling.enabledHint": "Varsayılan olarak kapalı. Yalnızca yerel çıkışta, örnekleme hızları ölçülmüş bir DAC’ta. macOS ve Windows’ta yalnızca paylaşımlı modda (özel modda ve ASIO’da değil); Linux’ta doğrudan hw: çıkışında da. Yerel DSD ve tamamen çözülen sıkıştırılmış akışlara upsampling uygulanmaz.",
  "upsampling.filter": "Filtre",
  "upsampling.filterHint": "Yalnızca bu makinenin gerçek zamanlı çalıştırabildiği filtreler (×3 payla) sunulur. Parantez içinde: seviye düşüşü.",
